import{clamp,scrollModel,locateScroll}from'./scroll-model.js';
const ids=['home','missions','mars','discover'],names=['Home','Explore','Mars','Discover'];
export function initJourney({showMission,hideMission}){
const panels=ids.map(id=>document.getElementById(id)),track=document.querySelector('.chapter-track'),journey=document.querySelector('#journey'),back=document.querySelector('#journey-back'),next=document.querySelector('#journey-next'),reduced=matchMedia('(prefers-reduced-motion: reduce)');
let current=0,model,position=0,target=0,frame=0,lastFrame=0,pointer=null,measuring=0,nativeEnd=0,wheelIdle=0;
const expected=panels.map(p=>p.scrollTop);
function parsed(){const[id,...parts]=location.hash.slice(1).split('/');return{index:Math.max(0,ids.indexOf(id)),mission:id==='missions'?parts.join('/')||null:null}}
function measure(){model=scrollModel(panels.map(p=>Math.max(0,p.scrollHeight-p.clientHeight)),clamp(innerHeight*.68,420,720))}
function savePosition(){history.replaceState({...history.state,chapterScroll:panels[current].scrollTop},'',location.href)}
function semantics(route,focus=false){current=route.index;const dock=document.querySelector('.explore-dock');dock.hidden=current!==1;dock.inert=current!==1;document.body.classList.toggle('explore-active',current===1);panels.forEach((p,i)=>{p.inert=i!==current;p.setAttribute('aria-hidden',String(i!==current));p.classList.toggle('is-current',i===current)});document.querySelectorAll('[data-chapter]').forEach(b=>{if(Number(b.dataset.chapter)===current)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current')});document.querySelectorAll('header nav a').forEach(a=>{if(a.hash==='#'+ids[current])a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});back.disabled=current===0&&!(history.state?.depth>0);next.innerHTML=current<3?names[current+1]+' <span>→</span>':'Explore <span>↗</span>';next.setAttribute('aria-label',current<3?'Next chapter: '+names[current+1]:'Explore Mars catalogue');document.querySelector('#chapter-status').textContent=`Chapter ${current+1} of 4: ${names[current]}`;document.title=names[current]+' — MarsPath';if(route.mission)showMission(route.mission);else hideMission();if(focus&&!route.mission)panels[current].focus({preventScroll:true})}
function cancel(){clearTimeout(wheelIdle);cancelAnimationFrame(frame);frame=0;lastFrame=0;track.classList.remove('wheel-driven')}
function commitWheelChapter(index){if(index===current)return;savePosition();history.pushState({horizon:true,index,mission:null,depth:(history.state?.depth||0)+1,chapterScroll:panels[index].scrollTop},'','#'+ids[index]);semantics({index,mission:null})}
function paint(){const at=locateScroll(model,position);track.style.transform=`translate3d(${-at.slide*innerWidth}px,0,0)`;if(at.scroll!==null){const index=at.index;expected[index]=at.scroll;panels[index].scrollTop=at.scroll}else{const left=Math.floor(at.slide),right=left+1;expected[left]=model.overflows[left];expected[right]=0;panels[left].scrollTop=expected[left];panels[right].scrollTop=0}commitWheelChapter(at.index)}
function tick(now){const dt=lastFrame?Math.min(40,now-lastFrame):16;lastFrame=now;position+=(target-position)*(1-Math.exp(-dt/110));if(Math.abs(target-position)<.35)position=target;paint();if(position!==target)frame=requestAnimationFrame(tick);else{frame=0;lastFrame=0;track.classList.remove('wheel-driven');savePosition()}}
function scrollToTarget(){track.classList.add('wheel-driven');if(reduced.matches){position=target;paint();track.classList.remove('wheel-driven');savePosition()}else if(!frame)frame=requestAnimationFrame(tick)}
function place(route,focus=false){cancel();semantics(route,focus);measure();const scroll=clamp(Number(history.state?.chapterScroll)||0,0,model.overflows[route.index]);position=target=model.starts[route.index]+scroll;expected[route.index]=scroll;panels[route.index].scrollTop=scroll;track.style.transform=`translate3d(${-route.index*innerWidth}px,0,0)`}
function go(index){index=clamp(index,0,ids.length-1);if(index===current&&!parsed().mission)return;cancel();savePosition();history.pushState({horizon:true,index,mission:null,depth:(history.state?.depth||0)+1,chapterScroll:panels[index].scrollTop},'','#'+ids[index]);place({index,mission:null},true)}
function previous(){if(history.state?.horizon&&history.state.depth>0)history.back();else if(current>0)go(current-1)}
function openMission(slug){if(parsed().mission===slug)return;savePosition();history.pushState({horizon:true,index:1,mission:slug,depth:(history.state?.depth||0)+1,chapterScroll:panels[1].scrollTop},'','#missions/'+slug);place({index:1,mission:slug})}
function closeMission(){if(parsed().mission){if(history.state?.depth>0)history.back();else{history.replaceState({horizon:true,index:1,mission:null,depth:0,chapterScroll:panels[1].scrollTop},'','#missions');place({index:1,mission:null})}}}
back.onclick=previous;next.onclick=()=>go(current<3?current+1:1);document.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>go(Number(b.dataset.chapter)));
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(!a)return;const index=ids.indexOf(a.hash.slice(1));if(index<0)return;e.preventDefault();go(index)});window.addEventListener('popstate',()=>place(parsed(),true));
document.addEventListener('keydown',e=>{if(document.querySelector('dialog').open||e.altKey||e.ctrlKey||e.metaKey||e.target.closest('input,textarea,select,[role=tablist],#viewer,#space'))return;if(e.key==='ArrowRight'){e.preventDefault();go(current+1)}else if(e.key==='ArrowLeft'){e.preventDefault();previous()}else if(e.key==='PageDown'||e.key==='PageUp'||e.key===' '&&!e.target.closest('button,a,summary')){e.preventDefault();measure();target=clamp(target+(e.key==='PageUp'||e.shiftKey?-1:1)*innerHeight*.65,0,model.max);scrollToTarget()}});
const wheelHandler=e=>{if(e.ctrlKey||document.querySelector('dialog').open||e.target.closest('select,textarea'))return;const raw=Math.abs(e.deltaX)>Math.abs(e.deltaY)*1.15?e.deltaX:e.deltaY,delta=raw*(e.deltaMode===1?18:e.deltaMode===2?innerHeight*.7:1);if(!delta)return;e.preventDefault();if(!frame){measure();const at=locateScroll(model,position);if(Math.abs(at.slide-current)<.001)position=target=model.starts[current]+panels[current].scrollTop}target=clamp(target+clamp(delta,-innerHeight*.8,innerHeight*.8),0,model.max);scrollToTarget();clearTimeout(wheelIdle);wheelIdle=setTimeout(()=>{const at=locateScroll(model,target);if(at.scroll===null){const left=Math.floor(at.slide);target=at.slide-left<.5?model.ends[left]:model.starts[left+1];scrollToTarget()}},180)};journey.addEventListener('wheel',wheelHandler,{passive:false});document.querySelector('.explore-dock').addEventListener('wheel',wheelHandler,{passive:false});
// Keep dragging the native scrollbar and touch scrolling synchronized with the wheel timeline.
panels.forEach((panel,index)=>panel.addEventListener('scroll',()=>{if(index!==current||Math.abs(panel.scrollTop-expected[index])<1)return;cancel();measure();expected[index]=panel.scrollTop;position=target=model.starts[index]+panel.scrollTop;clearTimeout(nativeEnd);nativeEnd=setTimeout(savePosition,120)},{passive:true}));
journey.addEventListener('pointerdown',e=>{if(e.target.closest('a,button,input,select,summary,#viewer,.fallback-globe,#space canvas,dialog')||e.button!==0)return;pointer={x:e.clientX,y:e.clientY,id:e.pointerId}});journey.addEventListener('pointerup',e=>{if(!pointer||pointer.id!==e.pointerId)return;const dx=e.clientX-pointer.x,dy=e.clientY-pointer.y;pointer=null;if(Math.abs(dx)>70&&Math.abs(dx)>Math.abs(dy)*1.5)go(current+(dx<0?1:-1))});journey.addEventListener('pointercancel',()=>pointer=null);
function resize(){if(measuring)return;measuring=requestAnimationFrame(()=>{measuring=0;if(frame)return;measure();position=target=model.starts[current]+panels[current].scrollTop;track.classList.add('wheel-driven');track.style.transform=`translate3d(${-current*innerWidth}px,0,0)`;requestAnimationFrame(()=>track.classList.remove('wheel-driven'))})}
window.addEventListener('resize',resize);const observer=new ResizeObserver(resize);document.querySelectorAll('#mission-grid,.field-layout,.field-launchpad,.discover-layout,.explore-dock').forEach(e=>observer.observe(e));
const initial=parsed();if(!history.state?.horizon){const base={horizon:true,index:initial.index,mission:null,depth:0,chapterScroll:0};if(initial.mission){history.replaceState(base,'','#missions');history.pushState({...base,mission:initial.mission,depth:1},'','#missions/'+initial.mission)}else history.replaceState(base,'',location.hash&&ids.includes(location.hash.slice(1).split('/')[0])?location.hash:'#home')}
place(initial);return{openMission,closeMission};
}
